package io.forgeloop.support.domain;
import java.time.Instant; import jakarta.persistence.*;
@Entity public class AuditEvent { @Id @GeneratedValue(strategy=GenerationType.UUID) private String id; private String action; private String ticketId; private String actorId; private String assigneeId; private Instant occurredAt; protected AuditEvent() {} public AuditEvent(String ticketId,String actorId,String assigneeId){this.action="TICKET_ASSIGNED";this.ticketId=ticketId;this.actorId=actorId;this.assigneeId=assigneeId;this.occurredAt=Instant.now();} public String getAction(){return action;} public String getTicketId(){return ticketId;} public String getActorId(){return actorId;} public String getAssigneeId(){return assigneeId;} public String getOccurredAt(){return occurredAt.toString();} }
